; Elite (Amstrad CPC) LARGEAXX.BIN, stock build: generated by tools/disasm_stock.py
; load address 0x0840, 4608 bytes. Names come from Fessor's reconstruction where known,
; otherwise sub_ (call target), loc_ (jump target), dat_ (data/variable reference).

; A key of the sell menu (sell_all.asm): -DENHANCED, English. With -DMISSIONS the routine sits in the stub, before the overlay (resident; the overlay is loaded after it)
    IFDEF ENHANCED
    DEFINE SELL_ALL
    ENDIF

; names of addresses in the other binaries
Viewdirection equ 0x1C02
circleOffsetY equ 0x20C7
circleOffsetXlo equ 0x20C8
circleOffsetXhi equ 0x20C9
fuelPriceByte equ 0x2F36
drawradius equ 0x20CA
charXY equ 0x38C4
FlightMode equ 0x38F8
Missionflag equ 0x3927
Checksum1 equ 0x3931
Checksum2 equ 0x3932
chkForIllegalGoods equ 0x398B
storedByteVariable equ 0x3E4E
sfxForKeyInput equ 0x3E4F
WaitForKeypress equ 0x3E5E
clearKeyBuffer equ 0x3E6C
askBuyGood equ 0x3E77
prQuantityofGoodinCargohold equ 0x3ECD
printTokenAndToken0x20 equ 0x3F03
CallprintString equ 0x3F0B
placeCursor equ 0x3F0E
printFollowingTokenWithSpace equ 0x3F21
SUB_ram_3f25 equ 0x3F25
VerticalPlacement equ 0x3F2D
ClearCharAtpos equ 0x3F3A
DrawBytesMask0 equ 0x3F56
printPlanetname equ 0x3F8C
printCleartext equ 0x3FDD
parseStoredToken equ 0x4002
todoReturnPressed equ 0x4030
longDelay equ 0x4042
bufferCharXY equ 0x4048
clrLine0x15 equ 0x404F
getMoneyinHLDE equ 0x4209
cashHome equ 0x1FEA                  ; commonxx.asm, end of the dead block (-DENHANCED)
clrLine0x16 equ 0x405B
restoreCharXY equ 0x406C
InputString equ 0x40AB
DrawFramedTitlebox equ 0x41A5
SetTableBegintoAofHL equ 0x41AA
printNumber equ 0x41BD
todo_SomethingwithDigits equ 0x41C1
printDeciCredit equ 0x4210
CurHomeinFrame equ 0x439D
printStringFollowingByte equ 0x43D8
printString equ 0x43DC
printStringA equ 0x4416
setColors equ 0x454F
drawFrame equ 0x4646
CommanderStatus equ 0x4847
getRank equ 0x4956
printMissionText equ 0x49D6
drawFlipChart equ 0x4A06
Inventory equ 0x4A40
ClearSaveGameRam equ 0x4A9E
setFuel equ 0x4EFF
listFilecatalog equ 0x84FD
smc_patchFWTextfunctions equ 0x8542
loadFile equ 0x8667
SaveSavegame equ 0x8693
DrawCircle equ 0xE73D
getMoney equ 0xFE56
AddDEtoMoney equ 0xFE6A
SbcDEfromMoney equ 0xFE72
tryPayForGood equ 0xFE80

 org 0x0840

; ZX Spectrum: buy_cargo (&E6AE)
; Key 2 (docked only): the buy cargo screen.
BuyGoods:
    ld a,(Missionflag)
    bit 5,a
    jr nz,refuseBacktoInventory
    ld a,(FlightMode)
    and a
    jr z,MarketBuyGoods
    ld a,0x5B
    ld de,0x4A22
    ld hl,0x1401  ; text cursor position for the message
    call drawFlipChart
    ld a,0x32
    ld (circleOffsetXlo),a
    ld a,0x00
    ld (circleOffsetY),a
    ld a,0x0C
    ld (circleOffsetXhi),a
    ld a,0x2D
    ld (drawradius),a
    call DrawCircle
    call WaitForKeypress
    cp 0x59
    jr nz,refuseBacktoInventory
    ld (0x38FB),a
    xor a
    ld (0x38F3),a
    ld hl,0x38E2
    ld b,0x11
initMissionSupernova:
    ld (hl),a
    inc hl
    djnz initMissionSupernova
    ld hl,0x3927
    set 5,(hl)
refuseBacktoInventory:
    ld a,0x0C
    ld (Viewdirection),a
    call longDelay
    jp Inventory
MarketBuyGoods:
    call drawFrame
    call printFollowingTokenWithSpace
    db 0x10
    ld a,0xFF
    call CallprintString
    ld de,0x4568
    call setColors
    call setPointerstoBeginofInventories
    ld hl,0x3914
    ld (0xEFFA),hl
mbloopEntries:
    ld hl,(0xEFF6)
    inc hl
    ld (0xEFF6),hl
    call askBuyGood
    jr c,LAB_ram_08db
    call bufferCharXY
LAB_ram_08c0:
    call printInputQuestionforQuantity
    ld hl,buyQuantityofGood
    call getInputForFunctionHL
    jr nc,LAB_ram_08d5
    cp 0x01
    jr z,LAB_ram_08c0
    cp 0x02
    jr z,LAB_ram_08d8
    jr loc_08E4
LAB_ram_08d5:
    call printWithTokens03n07
LAB_ram_08d8:
    call restoreCharXY
LAB_ram_08db:
    ld hl,0x3E4E
    inc (hl)
    ld a,(hl)
    cp 0x11
    jr c,mbloopEntries
loc_08E4:
    jp Inventory
    IFDEF ENHANCED
; Cash on the quantity line (-DENHANCED): the 16 dead bytes here (a ZX Spectrum attribute fill, never called) hold clrLine0x15 plus the balance
; at the right of the line below the prompt, where the typed quantity appears (8 characters, ends at column 30). cashHome puts the cursor back on row &15.
clrLineCash:
    call clrLine0x15
    ld hl,0x1616
    ld (charXY),hl
    call getMoneyinHLDE
    jp cashHome
    db 0x00
    ELSE
    db "!",0x00,"X",0xCD,0xF0,0x08,0xCD,0xF0,0x08,0x06,0x00,"w#",0x10,0xFC,0xC9
    ENDIF
LAB_ram_08f7:
    call ClearCharAtpos
    call restore_trade_state
    jr todoInputNumber1to9
; ZX Spectrum: read_trade_quantity (&E776)
; Reads a one- or two-digit quantity; HL is the row handler (buyQuantityofGood, sellQuantityofGood or the equipment handler), called as each digit is typed.
getInputForFunctionHL:
    ld (storedCallAddress),hl
todoInputNumber1to9:
    xor a
    ld (todo_storestringnumber),a
loopWaitforValidInput:
    call WaitForKeypress
    cp 0x0D
    jr z,doActionforReturn
    cp 0x31
    jr c,loopWaitforValidInput
    cp 0xFE
    jr z,loopWaitforValidInput
    cp 0x3A
    jr nc,LAB_ram_095f
    ld b,a
    sub 0x30
    ld (todo_storestringnumber),a
    ld a,b
    call printString
    ld hl,(storedCallAddress)
    call CallJPHL
    jr c,LAB_ram_095f
todoInputNumber0to9:
    call WaitForKeypress
    cp 0x0D
    ret z
    cp 0x30
    jr c,todoInputNumber0to9
    cp 0xFE
    jr z,LAB_ram_08f7
    cp 0x3A
    IFDEF ENHANCED
; Esc (or any non-digit) at the second digit undoes the first digit's trade like DEL does; the stock jump to LAB_ram_095f left it applied.
    jr nc,LAB_ram_08f7
    ELSE
    jr nc,LAB_ram_095f
    ENDIF
escQtyOperand equ $ - 1
    ld d,a
    sub 0x30
    ld b,a
    ld hl,todo_storestringnumber
    ld a,(hl)
    add a,a
    ld c,a
    add a,a
    add a,a
    add a,c
    add a,b
    ld (hl),a
    ld a,d
    call printString
    call restore_trade_state
    ld hl,(storedCallAddress)
    call CallJPHL
    jr c,LAB_ram_095f
    and a
    ret
doActionforReturn:
    ld a,0x02
LAB_ram_095f:
    scf
    ret
; Prints message token 3 (with space) then token 7, then ends via the error beep/delay tail
printWithTokens03n07:
    call printFollowingTokenWithSpace
    db 0x03
    call printStringFollowingByte
    db 0x07
    jp SUB_ram_09c4
; Trampoline: jumps to the address in HL, so `call CallJPHL` acts as an indirect call
CallJPHL:
    jp (hl)
; ZX Spectrum: buy_commodity_row (&E7DB)
buyQuantityofGood:
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    ld b,a
    ld hl,(0xEFFA)
    ld a,(hl)
    sub b
    jr c,errorforWrongQuantity
    ld (hl),a
bgLoopThroughStationInventory:
    ld hl,(0xEFF8)
    ld e,(hl)
    inc hl
    ld d,(hl)
    call tryPayForGood
    jr c,errorforNotEnoughCash
    djnz bgLoopThroughStationInventory
    call todoReturnPressed
    ld a,(todo_storestringnumber)
    ld b,a
    jr nc,LAB_ram_099a
    ld hl,0x38F3
    ld a,(hl)
    sub b
    IFDEF FIREBIRD
    db 0x38, 0x00   ; jr c,errorforNotEnoughCapacity in the Gold build
    ELSE
    jr c,errorforNotEnoughCapacity
    ENDIF
    ld (hl),a
LAB_ram_099a:
    ld hl,(0xEFF6)
    ld a,(hl)
    add a,b
    jr c,errorforNotEnoughCapacity
    ld (hl),a
    ld a,(storedByteVariable)
    call chkForIllegalGoods
    and a
    ret
errorforWrongQuantity:
    ld a,0xB0
    jr bgprintError
; Trade error: loads message token &C5 and falls into the shared error printer
errorforNotEnoughCash:
    ld a,0xC5
    jr bgprintError
errorforNotEnoughCapacity:
    ld a,0xCE
bgprintError:
    push af
    call printFollowingTokenWithSpace
    db 0x03
    pop af
    call printString
    call printStringFollowingByte
    db "?"
    call restore_trade_state
; Error/finish tail for the trade screen: key sound, long delay, returns A=1 with carry set
SUB_ram_09c4:
    call sfxForKeyInput
    call longDelay
    ld a,0x01
    scf
    ret
; ZX Spectrum: snapshot_trade_state (&E83C)
; Saves the state a trade can change (cash, this row's market stock and held amount, hold space) so restore_trade_state can undo a partial transaction.
snapshot_trade_state:
    ld hl,(0x38DD)
    ld (tmpMoney),hl
    ld hl,(0x38DF)
    ld (tmpLoMoney),hl
    ld hl,(0xEFFA)
    ld a,(hl)
    ld (BYTE_ram_0a3b),a
    ld hl,(0xEFF6)
    ld a,(hl)
    ld (BYTE_ram_0a3a),a
    ld a,(0x38F3)
    ld (tmpCargoCapacity),a
    ret
; ZX Spectrum: restore_trade_state (&E85D)
; Writes the snapshot made by snapshot_trade_state back.
restore_trade_state:
    ld hl,(tmpMoney)
    ld (0x38DD),hl
    ld hl,(tmpLoMoney)
    ld (0x38DF),hl
    ld hl,(0xEFFA)
    ld a,(BYTE_ram_0a3b)
    ld (hl),a
    ld hl,(0xEFF6)
    ld a,(BYTE_ram_0a3a)
    ld (hl),a
    ld a,(tmpCargoCapacity)
    ld (0x38F3),a
    ret
; Clears the prompt line and prints the quantity question for the chosen good
printInputQuestionforQuantity:
    IFDEF ENHANCED
    call clrLineCash
    ELSE
    call clrLine0x15
    ENDIF
    ld a,0x01
    ld (0x3949),a
    call printStringFollowingByte
    db 0xCC
    ld a,0xD0
    ld b,a
    ld a,(storedByteVariable)
    add a,b
    call printString
    call printStringFollowingByte
    db "/"
    call parseStoredToken
    call printStringFollowingByte
    db " "
    ld a,0x3F
    jp CallprintString
tmpLoMoney:
    db 0x00,0x00
tmpMoney:
    db 0x00,0x00
BYTE_ram_0a3a:
    db 0x00
BYTE_ram_0a3b:
    db 0x00
tmpCargoCapacity:
    db 0x00
todo_storestringnumber:
    db 0x00
storedCallAddress:
    db 0x00,0x00
; ZX Spectrum: sell_cargo (&E8AE)
; Key 3 (docked only): the sell cargo screen.
SellGoods:
    ld a,(FlightMode)
    and a
    jr nz,CanSell
    ld hl,0x3927
    ld a,(hl)
    bit 5,a
    jr z,CanSell
    res 5,(hl)
    ld hl,0x38D9
    inc (hl)
    ld a,0x64
    ld (0x38F1),a
    ld a,0x23
    ld (0x38F3),a
    ld a,0x0F
    ld de,0x4A27
    ld hl,0x0700
    call printMissionText
    jp Inventory
CanSell:
    call DrawFramedTitlebox
    ld de,0x456D
    call setColors
    call printStringFollowingByte
    db 0xCD
    ld a,0xCE
    call printPlanetname
    call setPointerstoBeginofInventories
csLoopThroughInventory:
    ld hl,(0xEFF8)
    inc hl
    inc hl
    ld (0xEFF8),hl
    call prQuantityofGoodinCargohold
    jr c,csGotoNextGood
    call bufferCharXY
askForQuantityToSell:
    call printInputQuestionforQuantity
    ld hl,sellQuantityofGood
    call getInputForFunctionHL
    jr c,reAskifNotAllSold
    call printWithTokens03n07
LAB_ram_0a9f:
    call restoreCharXY
    call placeCursor
csGotoNextGood:
    ld hl,0x3E4E
    inc (hl)
    ld a,(hl)
    cp 0x11
    jp c,csLoopThroughInventory
    call 0x403E
    call 0x403E
    jr csGotoInventoryScreen
reAskifNotAllSold:
    dec a
    jr z,askForQuantityToSell
    dec a
    jr z,LAB_ram_0a9f
csGotoInventoryScreen:
    IFDEF SELL_ALL
    jp sellAllEntry                 ; A sells the whole hold first (sell_all.asm), every other key just leaves
    ELSE
    jp Inventory
    ENDIF
sellAllOperand equ $ - 2
; ZX Spectrum: sell_commodity_row (&E935)
sellQuantityofGood:
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    ld b,a
    ld hl,(0xEFF6)
    ld a,(hl)
    sub b
    jp c,errorforWrongQuantity
    ld (hl),a
    push bc
    call todoReturnPressed
    pop bc
    jr nc,LAB_ram_0ade
    ld a,(0x38F3)
    add a,b
    ld (0x38F3),a
LAB_ram_0ade:
    push bc
    ld hl,(0xEFF8)
    ld e,(hl)
    inc hl
    ld d,(hl)
    call getMoney
    pop bc
    djnz LAB_ram_0ade
    and a
    ret
; Points the trade pointers at the start of the cargo hold and the station inventory, resets the row
setPointerstoBeginofInventories:
    ld hl,0x38E1
    ld (0xEFF6),hl
    ld hl,0x3E2A
    ld (0xEFF8),hl
    xor a
    ld (storedByteVariable),a
    ret
EquipShip:
    call DrawFramedTitlebox
    ld de,0x4572
    call setColors
    call printStringFollowingByte
    db 0x06
    ld a,0xCF
    call printTokenAndToken0x20
    call printStringFollowingByte
    db 0xB9
    call printStringFollowingByte
    db 0x08
    call CurHomeinFrame
    ld hl,0x2F35
    ld (pointerTblEquipmentprices),hl
    ld a,(0x3913)   ; presentTechLevel
    add a,0x02
    cp 0x0C
    jr c,LAB_ram_0b2c
    ld a,0x0E
LAB_ram_0b2c:
    ld (varEQMaxTechlevel),a
    xor a
listAvailableEquipmentloop:
    ld (varEquipmentNumber),a
    and a
    jr nz,LAB_ram_0b3c
    ld a,(FlightMode)
    and a
    jr nz,LAB_ram_0b6e
LAB_ram_0b3c:
    ld a,0x03
    ld (0x3947),a
    ld a,(varEquipmentNumber)
    inc a
    call printNumber
    call printFollowingTokenWithSpace
    db 0x04
    ld b,0x69
    ld a,(varEquipmentNumber)
    add a,b
    call printString
    call printFollowingTokenWithSpace
    db 0x16
    ld hl,(pointerTblEquipmentprices)
    ld a,(hl)
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    inc hl
    ld (pointerTblEquipmentprices),hl
    ld h,0x00
    ld l,a
    call printDeciCredit
    call placeCursor
LAB_ram_0b6e:
    ld a,(varEQMaxTechlevel)
    ld b,a
    ld a,(varEquipmentNumber)
    inc a
    cp b
    jr nz,listAvailableEquipmentloop
eqShoppingloop:
    IFDEF ENHANCED
    call clrLineCash
    ELSE
    call clrLine0x15
    ENDIF
    call printStringFollowingByte
    db 0x7F
    ld a,0x3F
    call printTokenAndToken0x20
    call snapshot_trade_state
    ld hl,AndsAandReturns
    call getInputForFunctionHL
    jr c,LAB_ram_0b9f
    call placeCursor
    ld a,(todo_storestringnumber)
    and a
    jp z,CommanderStatus
    ld b,a
    ld a,(varEQMaxTechlevel)
    cp b
LAB_ram_0b9f:
    jp c,CommanderStatus
    call snapshot_trade_state
    ld a,(todo_storestringnumber)
    call getEquipmentPriceEntry
    ld d,0x00
    ld e,(hl)
    push hl
    call SbcDEfromMoney
    pop hl
    jr c,eqFuel
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    call tryPayForGood
eqFuel:
    jp c,eqErrornotEnoughCash
    ld a,(todo_storestringnumber)
    cp 0x01
    jr nz,equipMissiles
    ld a,(FlightMode)
    and a
    jr nz,eqShoppingloop
    xor a
    ld (fuelPriceByte),a
    call printWithTokens03n07
    ld a,0x46
    call setFuel
    jp EquipShip
equipMissiles:
    cp 0x02
    jr nz,tryEquipLargeCargobay
    ld hl,0x38FA
    ld a,(hl)
    cp 0x04
    jp nc,eqErrorAllPresent
    inc a
    ld (hl),a
    jr eqContinueShopping
tryEquipLargeCargobay:
    cp 0x03
    jr nz,tryEquipECMSystem
    ld a,(0x38FB)
    and a
    jp nz,eqErrorEquipmentPresent
    ld hl,0x38F3
    ld a,(hl)
    add a,0x0F
    ld (hl),a
    jr equipIt
tryEquipECMSystem:
    cp 0x04
    jr z,chkIfEquipped
    cp 0x07
    jr c,tryEquipLasers
    cp 0x0D
    jr nc,tryEquipLasers
chkIfEquipped:
    call selectEquipmentOfShip
    ld a,(hl)
    and a
    jp nz,eqErrorEquipmentPresent
equipIt:
    call selectEquipmentOfShip
    ld (hl),0xFF
eqContinueShopping:
    call printWithTokens03n07
    jp eqShoppingloop
tryEquipLasers:
    ld b,0x01
    cp 0x05
    jr z,eqBuildLaserEQScreen
    inc b
    cp 0x06
    jr z,eqBuildLaserEQScreen
    inc b
    cp 0x0D
    jr z,eqBuildLaserEQScreen
    inc b
eqBuildLaserEQScreen:
    ld a,b
    ld (eqLasernumber),a
    push bc
    call drawFrame
    pop bc
    ld a,0x04
    add a,b
    call SUB_ram_3f25
    ld a,0x0E
    call VerticalPlacement
    ld a,(todo_storestringnumber)
    ld b,0x68
    add a,b
    call printString
    IFDEF ENHANCED
; Laser position by letter (ENHANCED): "F Front / B Back / L Left / R Right", keys F, B, L, R. The counter lives on the stack; the letters come from the
; reversed table eqLaserKeys (cpir leaves the view number in C); the block is padded so that eqErrornotEnoughCash stays at &0CC4 (docs/_my_changes.md).
eqLaserSlot:
    ld a,0x0F
    call VerticalPlacement
    call placeCursor                   ; row 0x10 as before, and it starts a word, so the first letter is a capital (the digit used to do that)
    xor a
eqListEquipmentdirections:
    push af
    call printFollowingTokenWithSpace
    db 0x0A
    pop af
    push af
    ld hl,eqLaserKeys+4
    cpl
    add a,l
    ld l,a
    ld a,(hl)
    call printTokenAndToken0x20
    pop af
    push af
    add a,0x60
    call CallprintString
    pop af
    inc a
    cp 0x04
    jr c,eqListEquipmentdirections
    call clrLine0x15
    call printStringFollowingByte
    db 0xAF
    call printStringFollowingByte
    db "?"
    call WaitForKeypress
    ld hl,eqLaserKeys
    ld bc,0x0004
    cpir
    jr nz,eqLaserLeave
    push bc
    call CallprintString
    pop bc
    ld a,c
    ELSE
    ld a,0x10
    call VerticalPlacement
    xor a
eqListEquipmentdirections:
    ld (varEquipmentNumber),a
    call printFollowingTokenWithSpace
    db 0x0A
    ld a,(varEquipmentNumber)
    add a,0x30
    call printTokenAndToken0x20
    ld a,(varEquipmentNumber)
    add a,0x60
    call CallprintString
    ld a,(varEquipmentNumber)
    inc a
    cp 0x04
    jr c,eqListEquipmentdirections
    call clrLine0x15
    call printStringFollowingByte
    db 0xAF
    call printStringFollowingByte
    db "?"
    call WaitForKeypress
    cp 0x30
    jp c,LAB_ram_0cbf
    cp 0x34
    jp nc,LAB_ram_0cbf
    push af
    call CallprintString
    pop af
    sub 0x30
    ENDIF
    ld hl,0x38F4
    call SetTableBegintoAofHL
    ld b,(hl)
    ld a,(eqLasernumber)
    ld (hl),a
    ld a,b
    and a
    jr z,eqLeaveNothingtoRefund
    ld hl,0x8DC3
    call SetTableBegintoAofHL
    ld a,(hl)
    call getEquipmentPriceEntry
    ld d,0x00
    ld e,(hl)
    push hl
    call AddDEtoMoney
    pop hl
    inc hl
    ld e,(hl)
    inc hl
    ld d,(hl)
    call getMoney
eqLeaveNothingtoRefund:
    call printWithTokens03n07
    jp EquipShip
    IFDEF ENHANCED
    ASSERT (eqLaserKeys & 0xFF) < 0xFC   ; the letter lookup adds to L only
eqLaserKeys:
    db "RLBF"                            ; Right Left Back Front: the reverse of the token order &60-&63, so cpir leaves the view number in C
    ASSERT $ <= 0x0CC4
    DS 0x0CC4-$                          ; eqErrornotEnoughCash and everything after it stay at their stock addresses
eqLaserSlotEnd:
    ELSE
LAB_ram_0cbf:
    call restore_trade_state
    jr LAB_ram_0cf7
    ENDIF
eqErrornotEnoughCash:
    IFDEF ENHANCED
    ASSERT eqErrornotEnoughCash == 0x0CC4   ; the stock address the laser block pads to
    ENDIF
    call errorforNotEnoughCash
    jp eqShoppingloop
AndsAandReturns:
    and a
    ret
; Points HL at the 3-byte price entry of the equipment item number in A
getEquipmentPriceEntry:
    dec a
    ld b,a
    add a,a
    add a,b
    ld hl,0x2F35
    jp SetTableBegintoAofHL
; Points HL at the ship's equipment slot for the selected item (table at &38F8)
selectEquipmentOfShip:
    ld hl,0x38F8
    ld a,(todo_storestringnumber)
    jp SetTableBegintoAofHL
eqErrorAllPresent:
    ld a,0x7C
    jr leaveEQScreen
eqErrorEquipmentPresent:
    ld a,0x68
    ld b,a
    ld a,(todo_storestringnumber)
    add a,b
leaveEQScreen:
    call printTokenAndToken0x20
    call printStringFollowingByte
    db 0x1E
    call SUB_ram_09c4
    IFDEF ENHANCED
eqLaserLeave:                          ; a key that is not F, B, L or R (the old LAB_ram_0cbf)
    ENDIF
    call restore_trade_state
LAB_ram_0cf7:
    jp CommanderStatus
varEQMaxTechlevel:
    db 0x00
varEquipmentNumber:
    db 0x00
pointerTblEquipmentprices:
    db 0x00,0x00
eqLasernumber:
    db 0x00
selectCassetteOrDisk:
