    xor a
    ld (filemenuvar),a
    ld (fmTempStack),sp
LAB_ram_0d38:
    call DrawFramedTitlebox
    ld a,0x01
    call printStringA
Filemenuloop:
    ld sp,(fmTempStack)
    ld de,0x4595
    call setColors
    call WaitForKeypress
    push af
    call clsFMInputLine
    pop af
    sub 0x31
    jr z,loadGame
    dec a
    jp z,saveGame
    dec a
    jp z,listFilecatalog
    dec a
    jr nz,Filemenuloop
    call SUB_ram_09c4
    call clearKeyBuffer
    ld a,(filemenuvar)
    and a
    ret nz
    xor a
    ret
    db "!w",0x0D,"~/w",0xC3,"8",0x0D
todo_inputvalue:
    db 0xFF
; Clears the file-menu input line on screen (30 character cells)
clsFMInputLine:
    ld b,0x1E
    ld hl,0xC3C2
LAB_ram_0d7d:
    push bc
    call DrawBytesMask0
    inc hl
    inc hl
    pop bc
    djnz LAB_ram_0d7d
    ret
colorsLoadGameMenu:
