; XORs the 104-byte commander block at &38CB with the code of EquipShip (save/load key)
encryptSAV:
    ld de,0x38CB
    ld hl,EquipShip
    ld b,0x68
loc_0F67:
    ld a,(de)
    xor (hl)
    ld (de),a
    inc hl
    inc de
    djnz loc_0F67
    ret
; XOR of 102 bytes of the commander block at &38CB (used as a save integrity check)
CryptRun1:
    ld hl,0x38CB
    ld b,0x66
    xor a
loc_0F75:
    xor (hl)
    inc hl
    djnz loc_0F75
    ret
; Returns in A the byte-sum of the first 103 bytes of the commander block at &38CB
getChecksum:
    ld hl,0x38CB
    ld b,0x67
    xor a
getchksumloop:
    add a,(hl)
    inc hl
    djnz getchksumloop
    ret
LAB_ram_0f85:
